/**
 * Reads environment variables from a specified file and loads them into process.env,
 * skipping comments and blank lines, while ensuring existing environment variables are never overridden.
 *
 * @param filePath The absolute or relative path to the secrets file. Defaults to ~/.secrets/agents.env if not provided.
 */
export function loadSecretsFromEnvFile(filePath: string = '~/.secrets/agents.env'): void {
    try {
        // Resolve the file path, handling the '~' expansion for home directory
        const absolutePath = path.resolve(filePath);

        if (!fs.existsSync(absolutePath)) {
            console.warn(`[SecretsLoader] File not found at: ${absolutePath}. Skipping load.`);
            return;
        }

        // Read file content synchronously for simplicity in a loader utility
        const content = fs.readFileSync(absolutePath, 'utf-8');

        const lines = content.split('\n');
        const newEnvVars: { [key: string]: string } = {};

        for (const line of lines) {
            // 1. Skip comments (starting with # or //) and blank lines
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#') || trimmedLine.startsWith('//')) {
                continue;
            }

            // 2. Parse KEY=VALUE format
            if (trimmedLine) {
                const separatorIndex = trimmedLine.indexOf('=');
                if (separatorIndex > 0) {
                    const key = trimmedLine.substring(0, separatorIndex).trim();
                    const value = trimmedLine.substring(separatorIndex + 1).trim();

                    if (key && value) {
                        // 3. Never override existing env vars: only store variables not already present in process.env
                        if (!process.env[key]) {
                            newEnvVars[key] = value;
                        } else {
                            console.warn(`[SecretsLoader] Skipping setting for '${key}'. Environment variable already exists.`);
                        }
                    }
                }
            }
        }

        // 4. Load only the new variables into process.env
        Object.assign(process.env, newEnvVars);
        console.log(`[SecretsLoader] Successfully loaded ${Object.keys(newEnvVars).length} new environment variables.`);

    } catch (error) {
        console.error(`[SecretsLoader] Failed to load secrets from ${filePath}:`, error instanceof Error ? error.message : error);
    }
}

