  import time
  from typing import Dict, Any
  
  class EventuallyConsistentStore:
      def __init__(self):
          # Store format: {key: {'value': str, 'timestamp': float}}
          self.store: Dict[str, Dict[str, Any]] = {}
  
      def get(self, key: str) -> Dict[str, Any] | None:
