      def apply_update(self, key: str, new_value: str, timestamp: float) -> None:
          current_state = self.store.get(key)
  
          if not current_state or timestamp > current_state['timestamp']:
              # New update is newer, apply it (Last Write Wins)
              self.store[key] = {'value': new_value, 'timestamp': timestamp}
              print(f"[Python] Updated {key}: New value \"{new_value}\" at time {timestamp:.2f}")
          elif timestamp < current_state['timestamp']:
              # Incoming update is older, ignore it
              print(f"[Python] Ignored update for {key}: Incoming time {timestamp:.2f} is older than current time {current_state['timestamp']:.2f}")
          else:
