              print(f"[Python] No change for {key}: Timestamps are equal.")
  
      def simulate_concurrent_updates(self, key: str, updates: list[Dict[str, float]]):
          print("\n--- Starting Concurrent Updates Simulation ---")
          for update in updates:
              self.apply_update(key, update['value'], update['time'])
          print("--- Concurrent Updates Finished ---\n")
  
      def print_state(self, key: str) -> Dict[str, Any] | None:
